<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller;use App\Models\EmployeeLifecycleChecklist;use App\Models\EmployeeLifecycleChecklistItem;use App\Models\LifecycleChecklistTemplate;use App\Models\LifecycleChecklistTemplateItem;use App\Models\WorkspaceMember;use App\Services\HRIS\HrisAccessService;use Carbon\Carbon;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
/** Provides hris lifecycle controller behavior within the WorkIntel application. */ class HrisLifecycleController extends Controller{
 /** Initializes the class with its required dependencies and state. */ public function __construct(private readonly HrisAccessService $access){}
 /** Handles the templates operation for the current WorkIntel workflow. */ public function templates(Request $request):JsonResponse{$workspace=$request->attributes->get('workspace');return response()->json(['data'=>LifecycleChecklistTemplate::query()->where('workspace_id',$workspace->id)->with('items')->orderBy('type')->orderBy('name')->get()]);}
 /** Handles the store template operation for the current WorkIntel workflow. */ public function storeTemplate(Request $request):JsonResponse{$workspace=$request->attributes->get('workspace');$actor=$request->attributes->get('workspaceMember');abort_unless($actor->hasPermission('hris.lifecycle.manage'),403);$data=$request->validate(['name'=>'required|string|max:140','type'=>'required|in:onboarding,offboarding,role_change,promotion,probation','status'=>'nullable|in:active,inactive','items'=>'required|array|min:1','items.*.title'=>'required|string|max:180','items.*.description'=>'nullable|string|max:2000','items.*.owner_type'=>'required|in:employee,manager,hr,it,payroll','items.*.due_offset_days'=>'required|integer|min:-365|max:365','items.*.required'=>'sometimes|boolean']);return DB::transaction(function()use($request,$workspace,$data){$template=LifecycleChecklistTemplate::create(['uuid'=>(string)Str::uuid(),'workspace_id'=>$workspace->id,'name'=>$data['name'],'type'=>$data['type'],'status'=>$data['status']??'active','created_by'=>$request->user()->id]);foreach($data['items'] as $i=>$row)LifecycleChecklistTemplateItem::create(['template_id'=>$template->id,'sort_order'=>($i+1)*10,...$row]);return response()->json(['data'=>$template->load('items')],201);});}
 /** Handles the member checklists operation for the current WorkIntel workflow. */ public function memberChecklists(Request $request,WorkspaceMember $member):JsonResponse{$workspace=$request->attributes->get('workspace');$actor=$request->attributes->get('workspaceMember');abort_unless((int)$member->workspace_id===(int)$workspace->id,404);$this->access->assertCanView($actor,$member);return response()->json(['data'=>EmployeeLifecycleChecklist::query()->where('workspace_id',$workspace->id)->where('member_id',$member->id)->with('items')->latest()->get()]);}
 /** Handles the start operation for the current WorkIntel workflow. */ public function start(Request $request,WorkspaceMember $member):JsonResponse{$workspace=$request->attributes->get('workspace');$actor=$request->attributes->get('workspaceMember');abort_unless((int)$member->workspace_id===(int)$workspace->id,404);abort_unless($actor->hasPermission('hris.lifecycle.manage'),403);$data=$request->validate(['template_id'=>'required|integer','effective_date'=>'required|date','name'=>'nullable|string|max:140']);$template=LifecycleChecklistTemplate::query()->where('workspace_id',$workspace->id)->where('status','active')->with('items')->findOrFail($data['template_id']);return DB::transaction(function()use($request,$workspace,$member,$data,$template){$effective=Carbon::parse($data['effective_date']);$checklist=EmployeeLifecycleChecklist::create(['uuid'=>(string)Str::uuid(),'workspace_id'=>$workspace->id,'member_id'=>$member->id,'template_id'=>$template->id,'type'=>$template->type,'name'=>$data['name']??$template->name,'effective_date'=>$effective->toDateString(),'status'=>'active','created_by'=>$request->user()->id]);foreach($template->items as $row)EmployeeLifecycleChecklistItem::create(['checklist_id'=>$checklist->id,'title'=>$row->title,'description'=>$row->description,'owner_type'=>$row->owner_type,'due_date'=>$effective->copy()->addDays($row->due_offset_days)->toDateString(),'required'=>$row->required,'sort_order'=>$row->sort_order]);return response()->json(['data'=>$checklist->load('items')],201);});}
 /** Handles the complete item operation for the current WorkIntel workflow. */ public function completeItem(Request $request,EmployeeLifecycleChecklistItem $item):JsonResponse{$workspace=$request->attributes->get('workspace');$actor=$request->attributes->get('workspaceMember');$checklist=EmployeeLifecycleChecklist::query()->where('workspace_id',$workspace->id)->findOrFail($item->checklist_id);$member=WorkspaceMember::query()->where('workspace_id',$workspace->id)->findOrFail($checklist->member_id);$roleSlugs=$actor->roles->pluck('slug')->all();$can=$actor->hasPermission('hris.lifecycle.manage')||($item->owner_type==='employee'&&(int)$actor->id===(int)$member->id)||($item->owner_type==='manager'&&(int)$member->manager_id===(int)$actor->id)||($item->owner_type==='hr'&&in_array('hr',$roleSlugs,true))||($item->owner_type==='payroll'&&in_array('payroll-manager',$roleSlugs,true));abort_unless($can,403,'This checklist task is assigned to another owner.');$data=$request->validate(['status'=>'required|in:completed,skipped,pending','completion_note'=>'nullable|string|max:3000']);$item->update(['status'=>$data['status'],'completion_note'=>$data['completion_note']??null,'completed_by'=>$data['status']==='completed'?$request->user()->id:null,'completed_at'=>$data['status']==='completed'?now():null]);$requiredOpen=$checklist->items()->where('required',true)->whereNot('status','completed')->exists();if(!$requiredOpen)$checklist->update(['status'=>'completed','completed_at'=>now()]);elseif($checklist->status==='completed')$checklist->update(['status'=>'active','completed_at'=>null]);return response()->json(['data'=>$checklist->fresh('items')]);}
}
